public long gcdScan(long a, long b) {
    if (a == 0) return b;
    if (b == 0) return a;
    long start = Math.min(a, b);
    for (long d = start; d >= 1; d--) {
        if (a % d == 0 && b % d == 0) {
            return d;
        }
    }
    return 1;
}

