def gcd_scan(self, a: int, b: int) -> int:
    if a == 0:
        return b
    if b == 0:
        return a
    for d in range(min(a, b), 0, -1):
        if a % d == 0 and b % d == 0:
            return d
    return 1

code.java:
public long gcd(long a, long b) {
    a = Math.abs(a);
    b = Math.abs(b);
    while (b != 0) {
        long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

public long lcm(long a, long b) {
    if (a == 0 || b == 0) return 0;
    long g = gcd(a, b);
    return a / g * b;   // divide first to avoid overflow
}

code.python:
def gcd(self, a: int, b: int) -> int:
    a, b = abs(a), abs(b)
    while b != 0:
        a, b = b, a % b
    return a

def lcm(self, a: int, b: int) -> int:
    if a == 0 or b == 0:
        return 0
    g = self.gcd(a, b)
    return a // g * b   # divide first to avoid overflow

